	UPDATE RAW_ACRF_DOC 	
		SET  
		main_tth_source = #{testTreatmentHistorySource} 
		,   pt_interview_date = #{dateReported} 
		,   ever_had_pos = #{prevPosHivTest} 
		,   first_hiv_test_ever = #{dateFirstPosHivTest} 
		,   ever_had_neg = #{negHivTest}
		,   last_neg_date = #{dateLastNegHivTest} 
		,   resp_hiv_test_2yrs = #{numNegTestUnkRef} 
		,   count_hiv_test_2yrs = #{numNegTestBeforePos} 
		,   pt_arv_6_mo = #{takenArvs} 
		,   pt_arv_name = #{arvMeds} 
		,   pt_arv_start_date = #{dateArvsBegan}
		,   pt_arv_end_date = #{dateLastUsedArvs} 
		WHERE		
		DOCUMENT_ID=#{documentId} and (ACRF_DOC_ID=#{acrfDocId} or PRF_DOC_ID=#{prfDocId} or AIRS_DOC_ID=#{airsDocId})

mapper.select:
SELECT DOCUMENT_ID documentId, ACRF_DOC_ID acrfDocId, PRF_DOC_ID prfDocId, AIRS_DOC_ID airsDocId, main_tth_source testTreatmentHistorySource, pt_interview_date dateReported, ever_had_pos prevPosHivTest, first_hiv_test_ever dateFirstPosHivTest, ever_had_neg negHivTest, last_neg_date dateLastNegHivTest, resp_hiv_test_2yrs numNegTestUnkRef, count_hiv_test_2yrs numNegTestBeforePos, pt_arv_6_mo takenArvs, pt_arv_name arvMeds, pt_arv_start_date dateArvsBegan, pt_arv_end_date dateLastUsedArvs
FROM RAW_TTH_DOC
WHERE ACRF_DOC_ID=#{acrfDocId} or PRF_DOC_ID=#{prfDocId} or AIRS_DOC_ID=#{airsDocId}
